const CFG = $('CONFIG').first().json;
const umbral = Number(CFG.diasUmbral || 10);
const repetir = Number(CFG.repetirCadaDias || 0);
const canal = String(CFG.discordCoordId || '').trim();
const canalOk = /^\d{5,}$/.test(canal);

const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
const ymd = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const parse = (s) => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s || '').trim()); return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null; };
const dmy = (d) => String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0');
const diasDesde = (d) => Math.round((hoy - d) / 86400000);

/* El Sheet no guarda desde cuándo un proyecto está en Listo para cierre, así que este
   workflow lo anota la primera vez que lo ve (memoria propia de n8n, solo en ejecuciones
   de producción con el workflow activo). Cubre tanto el cambio manual como el que hace wf11.
   Los que ya estén en cierre al activarlo empiezan a contar ese día. */
const st = $getWorkflowStaticData('global');
st.cierre = st.cierre || {};   /* { [id]: { desde:'YYYY-MM-DD', avisado:'YYYY-MM-DD' | '' } } */

const proyectos = $('Leer Projects').all().map(i => i.json).filter(r => r && r.id);
const enCierre = proyectos.filter(p => String(p.status || '').trim() === 'cierre');
const ids = new Set(enCierre.map(p => String(p.id)));
Object.keys(st.cierre).forEach(id => { if (!ids.has(id)) delete st.cierre[id]; });   /* completado, reabierto o borrado */

const progreso = (p) => {
  try {
    const items = (JSON.parse(p.checklist_json || '{}') || {}).cierre || [];
    return items.length ? items.filter(i => i && i.done).length + '/' + items.length : '';
  } catch (e) { return ''; }
};

const avisar = [];
for (const p of enCierre) {
  const id = String(p.id);
  const reg = st.cierre[id];
  if (!reg) { st.cierre[id] = { desde: ymd(hoy), avisado: '' }; continue; }   /* primer día visto */
  const desde = parse(reg.desde) || hoy;
  const n = diasDesde(desde);
  if (n < umbral) continue;
  const ultimo = parse(reg.avisado);
  const toca = !ultimo || (repetir > 0 && diasDesde(ultimo) >= repetir);
  if (toca) avisar.push({ p, reg, n, desde });
}

console.log('[wf17] en cierre ' + enCierre.length + ' · para avisar ' + avisar.length);
if (!avisar.length) return [];
if (!canalOk) { console.log('[wf17] discordCoordId sin configurar: no se manda nada'); return []; }

avisar.forEach(a => { a.reg.avisado = ymd(hoy); });
const lineas = ['⏳ **Proyectos en Listo para cierre hace más de ' + umbral + ' días**', ''];
avisar.sort((a, b) => b.n - a.n).slice(0, 20).forEach(a => {
  const pr = progreso(a.p);
  lineas.push('• **' + (a.p.nombre || a.p.id) + '** · hace ' + a.n + ' días (desde ' + dmy(a.desde) + ')' + (pr ? ' · checklist de cierre ' + pr : ''));
});
if (avisar.length > 20) lineas.push('…y ' + (avisar.length - 20) + ' más');
lineas.push('', 'Si ya están cerrados, pasalos a Completado.');
return [{ json: { channelId: canal, content: lineas.join('\n').slice(0, 1900) } }];
